_ZERO_DIGITS = {"CLP", "ISK", "JPY", "KRW", "UGX", "VND"}
_THREE_DIGITS = {"BHD", "JOD", "KWD", "OMR", "TND"}

# Link names (older aliases) that Meridale rejects, with the canonical id to send instead.
_CANONICAL_ZONES = {
    "US/Pacific": "America/Los_Angeles",
    "US/Eastern": "America/New_York",
    "US/Central": "America/Chicago",
    "Asia/Calcutta": "Asia/Kolkata",
    "Asia/Saigon": "Asia/Ho_Chi_Minh",
    "Europe/Kiev": "Europe/Kyiv",
    "America/Buenos_Aires": "America/Argentina/Buenos_Aires",
    "Brazil/East": "America/Sao_Paulo",
    "UTC": "Etc/UTC",
    "GMT": "Etc/UTC",
}

_OFFSET = re.compile(r"^(?:UTC|GMT)?\s*([+\-\u2212])\s*(\d{1,2})(?::?(\d{2}))?$")

# locale -> (decimal, group, code position, indian grouping, no grouping of 4-digit integers)
_LOCALES = {
    "en-US": (".", ",", "before", False, False),
    "en-GB": (".", ",", "before", False, False),
    "ja-JP": (".", ",", "before", False, False),
    "en-IN": (".", ",", "before", True, False),
    "pt-BR": (",", ".", "before", False, False),
    "de-DE": (",", ".", "after", False, False),
    "es": (",", ".", "after", False, True),
    "de-CH": (".", "\u2019", "after", False, False),
    "fr-FR": (",", "\u202f", "after", False, False),
}


def _zone(tz: str) -> str:
    """The canonical zone id Meridale accepts for a stored zone name or fixed offset."""
    tz = tz.strip()
    m = _OFFSET.match(tz)
    if m:
        hours, minutes = int(m.group(2)), int(m.group(3) or 0)
        if minutes:
            raise ValueError(f"unsupported fixed offset {tz!r}: only whole hours exist")
        east = m.group(1) == "+"
        if hours == 0:
            return "Etc/UTC"
        if hours > (14 if east else 12):
            raise ValueError(f"unsupported fixed offset {tz!r}")
        return f"Etc/GMT{'-' if east else '+'}{hours}"
    return _CANONICAL_ZONES.get(tz, tz)


def _locale(posix: str) -> str:
    """The BCP 47 locale Meridale supports that best matches a POSIX locale name."""
    name = re.split(r"[.@]", posix.strip(), maxsplit=1)[0]
    parts = re.split(r"[_\-]", name)
    language = parts[0].lower()
    region = parts[1].upper() if len(parts) > 1 and re.fullmatch(r"[A-Za-z]{2}", parts[1]) else ""
    if region and f"{language}-{region}" in _LOCALES:
        return f"{language}-{region}"
    if language in _LOCALES:
        return language
    return "en-US"


def _digits(currency: str) -> int:
    currency = currency.upper()
    return 0 if currency in _ZERO_DIGITS else 3 if currency in _THREE_DIGITS else 2


def _amount(value: str, digits: int) -> Decimal:
    return Decimal(value).quantize(Decimal(1).scaleb(-digits), rounding=ROUND_HALF_EVEN) + 0


def _group(integer: str, sep: str, indian: bool, skip_four: bool) -> str:
    if skip_four and len(integer) == 4:
        return integer
    if indian and len(integer) > 3:
        head, tail = integer[:-3], integer[-3:]
        pieces = []
        while len(head) > 2:
            pieces.insert(0, head[-2:])
            head = head[:-2]
        if head:
            pieces.insert(0, head)
        return sep.join(pieces + [tail])
    pieces = []
    while len(integer) > 3:
        pieces.insert(0, integer[-3:])
        integer = integer[:-3]
    return sep.join([integer] + pieces)


def _text(value: Decimal, currency: str, locale: str) -> str:
    decimal, group, position, indian, skip_four = _LOCALES[locale]
    digits = _digits(currency)
    value = value.quantize(Decimal(1).scaleb(-digits)) + 0
    sign = "-" if value < 0 else ""
    integer, _, fraction = f"{abs(value):f}".partition(".")
    number = sign + _group(integer, group, indian, skip_four) + (decimal + fraction if digits else "")
    return f"{currency}\u00a0{number}" if position == "before" else f"{number}\u00a0{currency}"
